package com.phonicsfun.core;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * LetterCatalogue - the A-Z picture vocabulary.
 *
 * GENERATED by scripts/generate-java-catalog.mjs from the canonical
 * JavaScript vocabulary in js/letter-data.js. Do not edit by hand: the
 * two stacks had three independent copies of this table, which is how
 * the native app came to teach words that had no recording.
 */
public final class LetterCatalog {

    private LetterCatalog() {
    }

    /** Letter -> the five picture words for that letter. */
    private static final Map<String, List<String>> WORDS = build();

    /** The available voice packs, by public id. */
    public static final List<String> VOICE_TEMPLATES = Collections.unmodifiableList(java.util.Arrays.asList(
        "american-male", "american-female", "british-female", "british-male"));

    private static Map<String, List<String>> build() {
        Map<String, List<String>> map = new LinkedHashMap<>();
        map.put("A", Collections.unmodifiableList(java.util.Arrays.asList("apple", "ant", "airplane", "alligator", "arrow")));
        map.put("B", Collections.unmodifiableList(java.util.Arrays.asList("ball", "bat", "bear", "boat", "butterfly")));
        map.put("C", Collections.unmodifiableList(java.util.Arrays.asList("cat", "car", "cake", "cloud", "crab")));
        map.put("D", Collections.unmodifiableList(java.util.Arrays.asList("dog", "duck", "drum", "dinosaur", "door")));
        map.put("E", Collections.unmodifiableList(java.util.Arrays.asList("elephant", "egg", "engine", "elbow", "earth")));
        map.put("F", Collections.unmodifiableList(java.util.Arrays.asList("fish", "frog", "flower", "feather", "firetruck")));
        map.put("G", Collections.unmodifiableList(java.util.Arrays.asList("grape", "goat", "gold", "girl", "grandpa")));
        map.put("H", Collections.unmodifiableList(java.util.Arrays.asList("hat", "hen", "house", "helicopter", "hippo")));
        map.put("I", Collections.unmodifiableList(java.util.Arrays.asList("igloo", "insect", "icecream", "island", "ink")));
        map.put("J", Collections.unmodifiableList(java.util.Arrays.asList("jellyfish", "jam", "jet", "jacket", "jungle")));
        map.put("K", Collections.unmodifiableList(java.util.Arrays.asList("kite", "kangaroo", "key", "kitten", "kettle")));
        map.put("L", Collections.unmodifiableList(java.util.Arrays.asList("lion", "lamp", "leaf", "ladder", "lemon")));
        map.put("M", Collections.unmodifiableList(java.util.Arrays.asList("moon", "monkey", "milk", "mountain", "mouse")));
        map.put("N", Collections.unmodifiableList(java.util.Arrays.asList("nest", "nose", "net", "night", "noodles")));
        map.put("O", Collections.unmodifiableList(java.util.Arrays.asList("octopus", "orange", "owl", "ocean", "oven")));
        map.put("P", Collections.unmodifiableList(java.util.Arrays.asList("pig", "pen", "pizza", "planet", "pumpkin")));
        map.put("Q", Collections.unmodifiableList(java.util.Arrays.asList("queen", "quilt", "quail", "quarter", "question")));
        map.put("R", Collections.unmodifiableList(java.util.Arrays.asList("rabbit", "rainbow", "robot", "rocket", "rose")));
        map.put("S", Collections.unmodifiableList(java.util.Arrays.asList("sun", "snake", "star", "sock", "sandwich")));
        map.put("T", Collections.unmodifiableList(java.util.Arrays.asList("tiger", "train", "tree", "turtle", "toothbrush")));
        map.put("U", Collections.unmodifiableList(java.util.Arrays.asList("umbrella", "unicorn", "up", "urn", "ukulele")));
        map.put("V", Collections.unmodifiableList(java.util.Arrays.asList("van", "vase", "vegetable", "violin", "volcano")));
        map.put("W", Collections.unmodifiableList(java.util.Arrays.asList("whale", "window", "watermelon", "wagon", "worm")));
        map.put("X", Collections.unmodifiableList(java.util.Arrays.asList("xylophone", "xray", "xerus", "xmas", "xenops")));
        map.put("Y", Collections.unmodifiableList(java.util.Arrays.asList("yacht", "yak", "yo-yo", "yellow", "yogurt")));
        map.put("Z", Collections.unmodifiableList(java.util.Arrays.asList("zebra", "zipper", "zoo", "zero", "zigzag")));
        return Collections.unmodifiableMap(map);
    }

    /**
     * The picture words for a letter.
     *
     * @param letter the letter, in any case
     * @return the words, or an empty list for an unknown letter
     */
    public static List<String> wordsForLetter(String letter) {
        if (letter == null) {
            return Collections.emptyList();
        }
        List<String> words = WORDS.get(letter.toUpperCase());
        return words == null ? Collections.<String>emptyList() : words;
    }

    /**
     * Every letter that has a vocabulary.
     *
     * @return the letters, in alphabetical order
     */
    public static List<String> letters() {
        return Collections.unmodifiableList(new java.util.ArrayList<>(WORDS.keySet()));
    }
}
